543	// StateStore provides low-level operations for managing session state files.
544	//
545	// StateStore is a primitive for session state persistence. It is NOT the same as
546	// the Sessions interface - it only handles state files in .git/entire-sessions/,
547	// not the full session data which includes checkpoint content.
548	//
549	// Use StateStore directly in strategies for performance-critical state operations.
550	// Use the Sessions interface (when implemented) for high-level session management.
551	type StateStore struct {
552		// stateDir is the directory where session state files are stored
553		stateDir string
554	}
555	
556	// NewStateStore creates a new state store.
557	// Uses the git common dir to store session state (shared across worktrees).
558	func NewStateStore(ctx context.Context) (*StateStore, error) {
559		commonDir, err := getGitCommonDir(ctx)
560		if err != nil {
561			return nil, fmt.Errorf("failed to get git common dir: %w", err)
562		}
563		return &StateStore{
564			stateDir: filepath.Join(commonDir, SessionStateDirName),
565		}, nil
566	}
567	
568	// NewStateStoreWithDir creates a new state store with a custom directory.
