574	// Load loads the session state for the given session ID.
575	// Returns (nil, nil) when session file doesn't exist or session is stale (not an error condition).
576	// Stale sessions (ended longer than StaleSessionThreshold ago) are automatically deleted.
577	func (s *StateStore) Load(ctx context.Context, sessionID string) (*State, error) {
578		// Validate session ID to prevent path traversal
579		if err := validation.ValidateSessionID(sessionID); err != nil {
580			return nil, fmt.Errorf("invalid session ID: %w", err)
581		}
582	
583		root, err := os.OpenRoot(s.stateDir)
584		if os.IsNotExist(err) {
585			return nil, nil //nolint:nilnil // nil,nil indicates session not found (expected case)
586		}
587		if err != nil {
588			return nil, fmt.Errorf("failed to open session state directory: %w", err)
589		}
590		defer root.Close()
591	
592		fileName := sessionID + ".json"
593		data, err := osroot.ReadFile(root, fileName)
594		if os.IsNotExist(err) {
595			return nil, nil //nolint:nilnil // nil,nil indicates session not found (expected case)
596		}
597		if err != nil {
598			return nil, fmt.Errorf("failed to read session state: %w", err)
599		}
600	
601		var state State
602		if err := json.Unmarshal(data, &state); err != nil {
603			return nil, fmt.Errorf("failed to unmarshal session state: %w", err)
604		}
605		state.NormalizeAfterLoad(ctx)
606	
607		if state.IsStale() {
608			logCtx := logging.WithComponent(ctx, "session")
609			logging.Debug(logCtx, "deleting stale session state",
610				slog.String("session_id", sessionID),
611			)
612			_ = s.Clear(ctx, sessionID) //nolint:errcheck // best-effort cleanup of stale session
613			return nil, nil             //nolint:nilnil // stale session treated as not found
614		}
615	
616		return &state, nil
617	}
